"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78088"],{38809(e){e.exports=JSON.parse('{"id":"F306","slug":"zero-coupon-bond","name":"Zero-Coupon Bond and STRIPS","subject":"Fixed Income","section":"Bonds","topic":"Zero-coupon bonds and STRIPS","level":"Beginner","aliases":["STRIPS","zero coupon price","accretion","imputed interest","deep discount bond"],"formula":{"latex":"P=\\\\frac{F}{(1+y/m)^{n\\\\,m}}","also":[],"text":"Price = Face value / (1 + yield / payments per year)^(years x payments per year)"},"symbols":[{"symbol":"F","meaning":"Face value paid at maturity","unit":"money"},{"symbol":"y","meaning":"Annual yield","unit":"per year"},{"symbol":"m","meaning":"Compounding periods per year (usually 2 for US bonds)","unit":"number"},{"symbol":"n","meaning":"Years to maturity","unit":"years"}],"when_to_use":"Use it to price a bond with a single payment at the end, including STRIPS, which are the coupons and principal of government bonds sold separately. Interest accrues as the price rises toward face value, and holders are often taxed on that accrual each year even though no cash arrives. Its duration equals its maturity.","worked_example":{"problem":"A zero-coupon bond has a face value of 1,000, matures in 15 years and yields 4.5% with semi-annual compounding. What is its price, and how much does it accrete in the first year?","inputs":{"face":1000,"y":4.5,"n":15,"m":2},"steps":[{"label":"Price = face / (1 + y/m)^(n x m)","working":"1000 / (1+0.045 / 2)^(15 x 2)","value":"512.98"},{"label":"Price one year later","working":"1000 / (1+0.045 / 2)^((15-1) x 2)","value":"536.32"},{"label":"Accretion in year one = later price - price now","working":"536.324-512.98","value":"23.34"}],"answer":"The price is 512.98. A year later, at the same yield, it is worth 536.32, so 23.34 of interest accrues even though nothing is paid. Its duration equals its maturity, 15 years."},"calculator":{"available":true,"inputs":[{"id":"face","label":"Face value","unit":"money","type":"number","default":1000,"hint":""},{"id":"y","label":"Yield","unit":"%","type":"number","default":4.5,"hint":""},{"id":"n","label":"Years to maturity","unit":"years","type":"number","default":15,"hint":"","min":1},{"id":"m","label":"Compounding per year","unit":"number","type":"number","default":2,"hint":"","min":1}],"checks":[],"steps":[{"id":"p0","label":"Price = face / (1 + y/m)^(n x m)","expr":"face/(1+y/m)^(n*m)","format":"money"},{"id":"p1","label":"Price one year later","expr":"face/(1+y/m)^((n-1)*m)","format":"money"},{"id":"acc","label":"Accretion in year one = later price - price now","expr":"p1-p0","format":"money"}],"results":["p0","acc"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"p0":512.980078425178,"p1":536.3238781190138,"acc":23.343799693835763}},"finder":{"finds":"The price of a zero-coupon bond and its accretion","needs":"Face value, yield, years"},"related":[{"slug":"bond-price","name":"Bond Price"},{"slug":"pv-lump-sum","name":"Present Value of a Lump Sum"},{"slug":"duration","name":"Macaulay and Modified Duration"}],"related_ids":["F284","F014","F288"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>P</mi><mo>=</mo><mfrac><mi>F</mi><mrow><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>y</mi><mi mathvariant=\\"normal\\">/</mi><mi>m</mi><msup><mo stretchy=\\"false\\">)</mo><mrow><mi>n</mi><mtext>\u2009</mtext><mi>m</mi></mrow></msup></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">P=\\\\frac{F}{(1+y/m)^{n\\\\,m}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"z-score","name":"Z-Score"},"next":null,"lesson":null,"total":522}')}}]);